/**
 * Candidate instance set for the flowai-core SWE-bench benchmark (FR-BENCH-SWE).
 *
 * The benchmark is single-arm: it runs flowai against instances the *published*
 * Claude-Sonnet baseline failed to resolve (sonnet-unsolved), cheapest-first.
 * Baseline is never re-run — every resolved candidate is a direct beat over the
 * published sonnet result.
 *
 * Data of record (both committed, regenerated by `benchmark select`):
 *   - sonnet_baseline.json — published resolved-id set + provenance.
 *   - candidates.json      — sonnet-unsolved, arm64-buildable, cheapest-first.
 *
 * Source of truth: documents/requirements.md FR-BENCH-SWE, documents/design.md §3.22.
 */

import type { Candidate } from "./select.ts";
import candidatesData from "./candidates.json" with { type: "json" };
import baselineData from "./sonnet_baseline.json" with { type: "json" };
import opusData from "./opus_baseline.json" with { type: "json" };
import poolData from "./pool.json" with { type: "json" };
import ccFailData from "./claude_code_opus_failures.json" with { type: "json" };

export type { Candidate } from "./select.ts";

/**
 * Repos excluded from candidate selection: heavy pinned C-extension builds that
 * fail on arm64 (Apple Silicon) swebench Docker images. Mirrors the deny-list
 * applied when generating candidates.json.
 */
export const ARM64_DENY: readonly string[] = [
  "matplotlib/matplotlib",
  "astropy/astropy",
  "scikit-learn/scikit-learn",
  "mwaskom/seaborn",
];

/** Published Claude-Sonnet baseline provenance + resolved-id set. */
export const SONNET_BASELINE: {
  source: string;
  runId: string;
  dataset: string;
  resolvedCount: number;
} = {
  source: baselineData.source,
  runId: baselineData.run_id,
  dataset: baselineData.dataset,
  resolvedCount: baselineData.resolved_count,
};

/** Instance ids the published sonnet baseline resolved. */
export const SONNET_RESOLVED: ReadonlySet<string> = new Set(
  baselineData.resolved,
);

/**
 * Published parity Claude-Opus baseline: SAME `tools` harness and date as the
 * sonnet baseline (`20250522`), only the model differs. `OPUS_RESOLVED −
 * SONNET_RESOLVED` is therefore the model-capability delta with the scaffold
 * held constant — the headroom set the POOL draws from.
 */
export const OPUS_BASELINE: {
  source: string;
  runId: string;
  dataset: string;
  resolvedCount: number;
} = {
  source: opusData.source,
  runId: opusData.run_id,
  dataset: opusData.dataset,
  resolvedCount: opusData.resolved_count,
};

/** Instance ids the published parity opus baseline resolved. */
export const OPUS_RESOLVED: ReadonlySet<string> = new Set(
  opusData.resolved,
);

/** Cheapest-first queue of sonnet-unsolved, arm64-buildable candidates. */
export const CANDIDATES: readonly Candidate[] = candidatesData as Candidate[];

/**
 * Headroom A/B pool (cheapest-first): instances the tools-Sonnet baseline FAILED
 * but the parity tools-Opus submission RESOLVED (`sonnet-fails ∩ opus-solves`),
 * arm64-buildable, short patches. Both bench arms run on Sonnet, so Opus is used
 * only as a tractability filter: these tasks are within reach of strong
 * reasoning but beyond a single Sonnet turn — the flowai process has measurable
 * headroom to close part of that Sonnet→Opus gap. Contrast the retired pool
 * (`sonnet-fails ∩ opus-fails`), which had zero headroom and floored the A/B at
 * the noise level.
 */
export const POOL: readonly Candidate[] = poolData as Candidate[];

/**
 * Retired pool-derivation input, kept as provenance only: published Claude Code
 * (Opus 4.5 + vexp) per-instance failures over a 100-instance subset. No longer
 * gates POOL membership — superseded by the full-dataset OPUS_RESOLVED parity
 * baseline above.
 */
export const CC_OPUS_FAILURES: {
  source: string;
  agent: string;
  model: string;
  failed: readonly string[];
} = ccFailData;

/** All pool instance ids, cheapest-first. */
export function poolIds(): string[] {
  return POOL.map((c) => c.instanceId);
}

/** Candidate lookup by instance id (POOL first, then the cheap candidate queue). */
export function candidateById(id: string): Candidate | undefined {
  return POOL.find((c) => c.instanceId === id) ??
    CANDIDATES.find((c) => c.instanceId === id);
}

/** The cheapest `n` candidate ids (the default run queue). */
export function cheapestIds(n: number): string[] {
  return CANDIDATES.slice(0, n).map((c) => c.instanceId);
}

/** All candidate ids in cheap-first order. */
export function allCandidateIds(): string[] {
  return CANDIDATES.map((c) => c.instanceId);
}
